 guide=[
  ("Where to post", "<ul><li>At the chlorine or hypochlorite feed room door.</li><li>At the bulk fill connection, so a delivery driver never connects acid to the hypochlorite line.</li><li>At cylinder and ton container storage.</li><li>At ventilation and leak alarm controls.</li></ul>"),
  ("Why mixing is the big one", "<p>Mixing sodium hypochlorite with an acid releases chlorine gas. Many plant incidents start at a fill connection where two chemicals are delivered side by side. A clear sign at each connection is a cheap safeguard.</p>"),
 ],
